/**
 * SCN-010 part C graft suite: firewall verdicts PINNED FROM origin/main
 * (128a0734), balanced mode, `analyzeFirewall(text, 'note', source, trust)`.
 *
 * GENERATED once against the base worktree's built dist, then frozen here as
 * literals: the head must reproduce every verdict and every blockedPatterns
 * list byte for byte (design scn-010c §6). None of these rows parses the
 * grammar G, so the change may not move any of them.
 *
 * Rows: every PREFERENCE_NOTE_NEGATIVES row (same ids), then a matrix of the
 * four design G sentences x the three HELD_ORDERS x seven joiners (space,
 * newline, `; `, `, `, ` and `, ` - `, em dash) x before/after, then four
 * 10 KB padding rows.
 *
 * Lanes: cli, memory_candidate, tool_result, web (each the bare label), and
 * `agent` = cli + `{ memoryAdmission: 'agent' }` (the MCP remember context).
 *
 * Non-ASCII characters are `\u` escapes so the bytes are visible in review.
 */

export type GraftLane = 'cli' | 'memory_candidate' | 'tool_result' | 'web' | 'agent';
export type GraftPin = readonly [result: string, blockedPatterns: readonly string[]];

